UTILS_SRC=src/utils.c
TEST_SRC=tests/test_main.c

# Output files
MAIN=main
TEST=tests/test_runner

# Default target
all: $(MAIN)

# Main executable
$(MAIN): $(MAIN_SRC) $(UTILS_SRC)
	@echo "Compiling main executable..."
	$(CC) $(CFLAGS) -o $@ $(MAIN_SRC) $(UTILS_SRC)
	@echo "Build successful: $(MAIN)"

# Test executable
$(TEST): $(TEST_SRC)
	@echo "Compiling test executable..."
	$(CC) $(CFLAGS) -o $@ $(TEST_SRC)
	@echo "Build successful: $(TEST)"

# Run tests with test runner
test: $(TEST)
	@echo "Running tests..."
	./$(TEST)

# Run tests with main executable
run-test: $(MAIN)
	@echo "Running tests with main executable..."
	./$(MAIN) --test

# Clean build artifacts
clean:
	@echo "Cleaning build artifacts..."
	rm -f $(MAIN) $(TEST)
	@echo 'Cleaned'

# Rebuild from scratch
rebuild: clean all

# Show help
help:
	@echo "Available targets:"
	@echo "  all       - Build main executable (default)"
	@echo "  test      - Build and run test suite"
	@echo "  run-test  - Build and run tests with main executable"
	@echo "  clean     - Remove build artifacts"
	@echo "  rebuild   - Clean and rebuild"
	@echo "  help      - Show this help message"

.PHONY: all test run-test clean rebuild help
EOF

